CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE campaigns(id TEXT PRIMARY KEY,active_branch TEXT NOT NULL,cursor INTEGER NOT NULL,status TEXT NOT NULL,pending_fork INTEGER NOT NULL DEFAULT 0);
CREATE TABLE branches(id TEXT PRIMARY KEY,campaign TEXT NOT NULL REFERENCES campaigns(id),parent TEXT REFERENCES branches(id),fork_cursor INTEGER NOT NULL,head INTEGER NOT NULL);
CREATE TABLE events(id TEXT PRIMARY KEY,branch TEXT NOT NULL REFERENCES branches(id),cursor INTEGER NOT NULL,origin TEXT UNIQUE NOT NULL,battle TEXT NOT NULL,record TEXT NOT NULL,ingested_at REAL NOT NULL,UNIQUE(branch,cursor));
CREATE TABLE launches(id TEXT PRIMARY KEY,nonce INTEGER UNIQUE NOT NULL,campaign TEXT NOT NULL REFERENCES campaigns(id),loaded_fingerprint TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE streams(nonce INTEGER NOT NULL,run INTEGER NOT NULL,launch TEXT NOT NULL REFERENCES launches(id),last INTEGER NOT NULL,state TEXT NOT NULL,PRIMARY KEY(nonce,run));
CREATE TABLE deliveries(identity TEXT PRIMARY KEY,launch TEXT NOT NULL REFERENCES launches(id),run INTEGER NOT NULL,sequence INTEGER NOT NULL,wire TEXT NOT NULL,event TEXT REFERENCES events(id),observation TEXT);
CREATE TABLE observations(id TEXT PRIMARY KEY,branch TEXT NOT NULL REFERENCES branches(id),cursor INTEGER NOT NULL,origin TEXT UNIQUE NOT NULL,record TEXT NOT NULL,ingested_at REAL NOT NULL);
CREATE TABLE projection(campaign TEXT PRIMARY KEY REFERENCES campaigns(id),state TEXT NOT NULL);
CREATE TABLE checkpoints(id TEXT PRIMARY KEY,campaign TEXT NOT NULL REFERENCES campaigns(id),branch TEXT NOT NULL REFERENCES branches(id),cursor INTEGER NOT NULL,fingerprint TEXT UNIQUE NOT NULL,save_identity TEXT NOT NULL,state_sha256 TEXT NOT NULL,build TEXT NOT NULL,schema INTEGER NOT NULL,reducer INTEGER NOT NULL,kind TEXT NOT NULL,created_at REAL NOT NULL);
CREATE TABLE save_intents(id TEXT PRIMARY KEY,campaign TEXT NOT NULL REFERENCES campaigns(id),branch TEXT NOT NULL,cursor INTEGER NOT NULL,nonce INTEGER NOT NULL,run INTEGER NOT NULL,last_sequence INTEGER NOT NULL,old_fingerprint TEXT NOT NULL,old_counter INTEGER NOT NULL,status TEXT NOT NULL,checkpoint TEXT REFERENCES checkpoints(id));
CREATE TABLE outbox(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL);
